PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS Utilisateurs (Id INTEGER PRIMARY KEY AUTOINCREMENT, Identifiant TEXT NOT NULL UNIQUE COLLATE NOCASE, MotDePasseHache TEXT NOT NULL, Role TEXT NOT NULL CHECK (Role IN ('Administrateur','Vendeur')));
CREATE TABLE IF NOT EXISTS Produits (Id INTEGER PRIMARY KEY AUTOINCREMENT, Reference TEXT NOT NULL UNIQUE COLLATE NOCASE, CodeBarres TEXT, Designation TEXT NOT NULL COLLATE NOCASE, Categorie TEXT NOT NULL COLLATE NOCASE, SeuilStockMinimum INTEGER NOT NULL DEFAULT 0 CHECK (SeuilStockMinimum >= 0), PrixVente NUMERIC NOT NULL DEFAULT 0 CHECK (PrixVente >= 0), IsArchive INTEGER NOT NULL DEFAULT 0 CHECK (IsArchive IN (0,1)));
CREATE TABLE IF NOT EXISTS Fournisseurs (Id INTEGER PRIMARY KEY AUTOINCREMENT, Nom TEXT NOT NULL COLLATE NOCASE, Telephone TEXT, Email TEXT, Adresse TEXT, IsArchive INTEGER NOT NULL DEFAULT 0 CHECK (IsArchive IN (0,1)));
CREATE TABLE IF NOT EXISTS Lots (Id INTEGER PRIMARY KEY AUTOINCREMENT, ProduitId INTEGER NOT NULL, NumeroLot TEXT NOT NULL, DatePeremption TEXT NOT NULL, QuantitePhysique INTEGER NOT NULL CHECK (QuantitePhysique >= 0), QuantiteVendable INTEGER NOT NULL CHECK (QuantiteVendable >= 0 AND QuantiteVendable <= QuantitePhysique), CoutAchat NUMERIC NOT NULL CHECK (CoutAchat >= 0), IsBloque INTEGER NOT NULL DEFAULT 0 CHECK (IsBloque IN (0,1)), FOREIGN KEY (ProduitId) REFERENCES Produits(Id) ON DELETE RESTRICT, UNIQUE (ProduitId, NumeroLot));
CREATE TABLE IF NOT EXISTS Ventes (Id INTEGER PRIMARY KEY AUTOINCREMENT, DateVente TEXT NOT NULL, ModePaiement TEXT NOT NULL CHECK (ModePaiement IN ('Especes','Carte','Mobile')), UtilisateurId INTEGER NOT NULL, SessionId INTEGER, Total NUMERIC NOT NULL CHECK (Total >= 0), Statut TEXT NOT NULL DEFAULT 'Terminee' CHECK (Statut IN ('Brouillon','Terminee','Annulee')), FOREIGN KEY (UtilisateurId) REFERENCES Utilisateurs(Id) ON DELETE RESTRICT, FOREIGN KEY (SessionId) REFERENCES CaisseSessions(Id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS LignesVente (Id INTEGER PRIMARY KEY AUTOINCREMENT, VenteId INTEGER NOT NULL, ProduitId INTEGER NOT NULL, LotId INTEGER NOT NULL, Quantite INTEGER NOT NULL CHECK (Quantite > 0), PrixVente NUMERIC NOT NULL CHECK (PrixVente >= 0), FOREIGN KEY (VenteId) REFERENCES Ventes(Id) ON DELETE CASCADE, FOREIGN KEY (ProduitId) REFERENCES Produits(Id) ON DELETE RESTRICT, FOREIGN KEY (LotId) REFERENCES Lots(Id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS MouvementsStock (Id INTEGER PRIMARY KEY AUTOINCREMENT, DateMouvement TEXT NOT NULL, LotId INTEGER NOT NULL, Quantite INTEGER NOT NULL CHECK (Quantite <> 0), Motif TEXT NOT NULL CHECK (Motif IN ('Vente','Perte','Reassort','Retour')), UtilisateurId INTEGER NOT NULL, FOREIGN KEY (LotId) REFERENCES Lots(Id) ON DELETE RESTRICT, FOREIGN KEY (UtilisateurId) REFERENCES Utilisateurs(Id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS LogsActions (Id INTEGER PRIMARY KEY AUTOINCREMENT, DateLog TEXT NOT NULL, UtilisateurId INTEGER, DescriptionAction TEXT NOT NULL, FOREIGN KEY (UtilisateurId) REFERENCES Utilisateurs(Id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS Receptions (Id INTEGER PRIMARY KEY AUTOINCREMENT, DateReception TEXT NOT NULL, FournisseurId INTEGER, ReferenceDocument TEXT, UtilisateurId INTEGER NOT NULL, Statut TEXT NOT NULL DEFAULT 'Validee' CHECK (Statut IN ('Brouillon','Validee','Annulee')), FOREIGN KEY (FournisseurId) REFERENCES Fournisseurs(Id) ON DELETE SET NULL, FOREIGN KEY (UtilisateurId) REFERENCES Utilisateurs(Id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS LignesReception (Id INTEGER PRIMARY KEY AUTOINCREMENT, ReceptionId INTEGER NOT NULL, ProduitId INTEGER NOT NULL, LotId INTEGER NOT NULL, Quantite INTEGER NOT NULL CHECK (Quantite > 0), CoutAchat NUMERIC NOT NULL CHECK (CoutAchat >= 0), FOREIGN KEY (ReceptionId) REFERENCES Receptions(Id) ON DELETE CASCADE, FOREIGN KEY (ProduitId) REFERENCES Produits(Id) ON DELETE RESTRICT, FOREIGN KEY (LotId) REFERENCES Lots(Id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS CaisseSessions (Id INTEGER PRIMARY KEY AUTOINCREMENT, DateOuverture TEXT NOT NULL, DateCloture TEXT, UtilisateurId INTEGER NOT NULL, FondCaisse NUMERIC NOT NULL CHECK (FondCaisse >= 0), TotalEspecesAttendu NUMERIC, TotalEspecesCompte NUMERIC, Ecart NUMERIC, Statut TEXT NOT NULL DEFAULT 'Ouverte' CHECK (Statut IN ('Ouverte','Cloturee')), FOREIGN KEY (UtilisateurId) REFERENCES Utilisateurs(Id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS MouvementsCaisse (Id INTEGER PRIMARY KEY AUTOINCREMENT, SessionId INTEGER NOT NULL, DateMouvement TEXT NOT NULL, UtilisateurId INTEGER NOT NULL, Montant NUMERIC NOT NULL CHECK (Montant <> 0), Motif TEXT NOT NULL, FOREIGN KEY (SessionId) REFERENCES CaisseSessions(Id) ON DELETE RESTRICT, FOREIGN KEY (UtilisateurId) REFERENCES Utilisateurs(Id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS Parametres (Cle TEXT PRIMARY KEY, Valeur TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS RetoursVente (Id INTEGER PRIMARY KEY AUTOINCREMENT, VenteId INTEGER NOT NULL, DateRetour TEXT NOT NULL, UtilisateurId INTEGER NOT NULL, Motif TEXT NOT NULL, Total NUMERIC NOT NULL CHECK (Total >= 0), FOREIGN KEY (VenteId) REFERENCES Ventes(Id) ON DELETE RESTRICT, FOREIGN KEY (UtilisateurId) REFERENCES Utilisateurs(Id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS LignesRetourVente (Id INTEGER PRIMARY KEY AUTOINCREMENT, RetourId INTEGER NOT NULL, LigneVenteId INTEGER NOT NULL, LotId INTEGER NOT NULL, Quantite INTEGER NOT NULL CHECK (Quantite > 0), Montant NUMERIC NOT NULL CHECK (Montant >= 0), FOREIGN KEY (RetourId) REFERENCES RetoursVente(Id) ON DELETE CASCADE, FOREIGN KEY (LigneVenteId) REFERENCES LignesVente(Id) ON DELETE RESTRICT, FOREIGN KEY (LotId) REFERENCES Lots(Id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS IX_Produits_Reference ON Produits(Reference COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS IX_Produits_Designation ON Produits(Designation COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS IX_Produits_Categorie_Actif ON Produits(IsArchive, Categorie, Designation COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS IX_Lots_FEFO ON Lots(ProduitId, IsBloque, DatePeremption, QuantiteVendable);
CREATE INDEX IF NOT EXISTS IX_LignesVente_Vente ON LignesVente(VenteId);
CREATE INDEX IF NOT EXISTS IX_MouvementsStock_Lot_Date ON MouvementsStock(LotId, DateMouvement);
CREATE INDEX IF NOT EXISTS IX_Ventes_Date ON Ventes(DateVente);
CREATE INDEX IF NOT EXISTS IX_Receptions_Date ON Receptions(DateReception);
CREATE INDEX IF NOT EXISTS IX_LignesReception_Reception ON LignesReception(ReceptionId);
CREATE INDEX IF NOT EXISTS IX_CaisseSessions_Statut ON CaisseSessions(Statut, DateOuverture);
CREATE INDEX IF NOT EXISTS IX_MouvementsCaisse_Session ON MouvementsCaisse(SessionId, DateMouvement);
CREATE INDEX IF NOT EXISTS IX_RetoursVente_Vente ON RetoursVente(VenteId);
